// Dev-only stand-in for @deepseek-ai/dsh-tools so the suite runs outside a DSH install.
// It is NOT a behaviour-free identity: it validates exactly what the real registry
// validates at registration time, so a schema mistake fails here rather than at host boot.
//
// Kept deliberately in sync with the real package's enforced subset:
//   type / oneOf / properties / required / additionalProperties / items / enum / const
//   + annotations (description, title, default, examples)
export const SUPPORTED_TYPES = ['object', 'array', 'string', 'number', 'integer', 'boolean', 'null']
const SUPPORTED_KEYWORDS = new Set([
  'type',
  'oneOf',
  'properties',
  'required',
  'additionalProperties',
  'items',
  'enum',
  'const',
  'description',
  'title',
  'default',
  'examples',
])

export class JsonSchemaError extends Error {
  constructor(message) {
    super(message)
    this.name = 'JsonSchemaError'
  }
}

function assertNode(node, path) {
  if (node === null || typeof node !== 'object') return
  if (Array.isArray(node)) {
    node.forEach((entry, index) => assertNode(entry, `${path}[${index}]`))
    return
  }
  if (Object.hasOwn(node, 'type')) {
    const type = node.type
    if (Array.isArray(type) || !SUPPORTED_TYPES.includes(type)) {
      throw new JsonSchemaError(`unsupported JSON schema: schema.type must be one of ${SUPPORTED_TYPES.join('/')}`)
    }
  }
  for (const [key, value] of Object.entries(node)) {
    if (!SUPPORTED_KEYWORDS.has(key)) throw new JsonSchemaError(`unsupported JSON schema: ${path}.${key} is not a supported keyword`)
    // `properties` keys are property names, not keywords: recurse into their schemas.
    if (key === 'properties' && value !== null && typeof value === 'object') {
      for (const [property, propertySchema] of Object.entries(value)) assertNode(propertySchema, `${path}.properties.${property}`)
      continue
    }
    // `additionalProperties` may be a boolean, which carries no schema to check.
    if (key === 'additionalProperties' && typeof value === 'boolean') continue
    assertNode(value, `${path}.${key}`)
  }
}

/** Same contract as the real validator: throw on anything outside the enforced subset. */
export function assertSupportedJsonSchema(schema) {
  if (schema === null || typeof schema !== 'object' || Array.isArray(schema)) {
    throw new JsonSchemaError('unsupported JSON schema: a schema must be an object')
  }
  assertNode(schema, 'schema')
  return schema
}

/** Identity wrapper, matching the real defineTool's "return a registry-ready definition" contract. */
export function defineTool(definition) {
  if (definition?.output?.schema !== undefined) assertSupportedJsonSchema(definition.output.schema)
  return definition
}
